102	/**
103	 * The reference figure with whatever adjustment a rule made to it. Rounded to
104	 * a whole number once it is big enough for a decimal to be noise — the
105	 * vegetarian iron figure lands on 32 mg and 14 mg, which is how ODS quotes it,
106	 * rather than 32.4 and 14.4.
107	 */
108	const scaled = (rda: number, factor: number) => {
109	  const v = rda * factor;
110	  return v >= 10 ? Math.round(v) : Math.round(v * 10) / 10;
111	};
