130	  const [entries, setEntries] = useState<GlossaryEntry[] | null>(null);
131	  const [refs, setRefs] = useState<Record<string, NutrientReference[]>>({});
132	  useEffect(() => {
133	    listGlossary(200)
134	      .then((rows) => {
135	        setEntries(rows);
136	        return getNutrientReference(rows.map((r) => r.id));
137	      })
138	      .then((m) => m && setRefs(m))
139	      .catch(() => setEntries([]));
140	  }, []);
141	
142	  return useMemo(() => {
143	    if (!entries) return null;
144	    const ids = goalIds.length ? goalIds : DEFAULT_GOAL_IDS;
145	    const goalNames = ids.map((g) => GOAL_BY_ID[g]?.name ?? g);
146	
147	    /* Everything the ordering knows is in lib/recommend.ts, including the
148	       sentence on each card. This screen picks how many to show and turns a
149	       reference intake into a string; it does not decide anything. */
150	    const result = recommend(entries, {
151	      goalTags: ids.flatMap((g) => GOAL_BY_ID[g]?.tags ?? []),
152	      goalLabel: goalNames.length > 1 ? 'your goals' : (goalNames[0]?.toLowerCase() ?? 'your goals'),
153	      currentStack,
154	      diet,
155	      reactions,
156	      forms,
157	    });
158	
159	    return {
160	      picks: result.ranked.slice(0, 6).map((s, i) => {
161	        const r = pickReference(refs[s.entry.id], age, sex);
162	        return {
163	          id: s.entry.id,
164	          name: s.entry.name,
165	          route: s.entry.route,
166	          amount: r?.rda != null ? `${scaled(r.rda, s.amountFactor)} ${r.unit}` : '',
167	          why: s.reason,
168	          withFood: s.timing === 'with_food',
169	          selected: i < 3,
170	        } satisfies Recommendation;
171	      }),
172	      leftOut: {
173	        alreadyTaking: result.alreadyTaking,
174	        swapped: result.swappedOut,
