303	/* ── the draggable schedule ──────────────────────────────────────────── */
304	
305	interface Slot {
306	  id: string;
307	  name: string;
308	  time: string;
309	}
310	
311	const buildSlots = (meals: Meal[], wake: string, sleep: string): Slot[] => {
312	  const s: Slot[] = [{ id: 'morning', name: 'Morning', time: wake }];
313	  for (const m of [...meals].sort((a, b) => toMinutes(a.time) - toMinutes(b.time))) {
314	    s.push({ id: m.id, name: m.name, time: m.time });
315	  }
316	  s.push({ id: 'winddown', name: 'Wind-down', time: fromMinutes(toMinutes(sleep) - 60) });
317	  const seen = new Set<string>();
318	  return s.filter((x) => (seen.has(x.time) ? false : (seen.add(x.time), true)));
319	};
320	
321	export function ScheduleBuilder({
322	  picks,
323	  meals,
324	  wake,
325	  sleep,
326	  onDone,
327	}: {
328	  picks: Recommendation[];
329	  meals: Meal[];
330	  wake: string;
331	  sleep: string;
332	  onDone: (schedule: { id: string; time: string }[]) => void;
333	}) {
334	  const slots = useMemo(() => buildSlots(meals, wake, sleep), [meals, wake, sleep]);
335	  const [placed, setPlaced] = useState<Record<string, string>>(() =>
336	    Object.fromEntries(picks.map((p, i) => [p.id, slots[i % slots.length].id])),
337	  );
338	  const [dragging, setDragging] = useState<string | null>(null);
339	  const [over, setOver] = useState<{ slot: string; bad: boolean } | null>(null);
340	  const [shake, setShake] = useState<string | null>(null);
341	  const [message, setMessage] = useState<string | null>(null);
342	  const hold = useRef<number | null>(null);
343	
344	  const ctx = { mealTimes: meals.map((m) => m.time), sleepTime: sleep };
345	  const slotById = Object.fromEntries(slots.map((s) => [s.id, s]));
346	
347	  const itemsIn = (slotId: string) => picks.filter((p) => placed[p.id] === slotId);
348	
349	  const others = (movingId: string): ScheduledItem[] =>
350	    picks
351	      .filter((p) => p.id !== movingId)
352	      .map((p) => ({ id: p.id, name: p.name, time: slotById[placed[p.id]]?.time ?? wake }));
353	
354	  const tryDrop = (id: string, slotId: string) => {
355	    const p = picks.find((x) => x.id === id)!;
356	    const target = slotById[slotId];
357	    const violations = checkPlacement({ id, name: p.name, time: target.time }, target.time, others(id), ctx);
358	    const blocking = violations.find((v) => v.severity === 'block');
359	    if (blocking) {
360	      // springs back, shakes, and says which rule -- the shake on its own
361	      // communicates nothing and fails accessibility
362	      setShake(id);
363	      setMessage(blocking.message);
364	      setTimeout(() => setShake(null), 420);
365	      return;
366	    }
367	    setPlaced((m) => ({ ...m, [id]: slotId }));
368	    setMessage(violations[0]?.message ?? null);
369	  };
370	
371	  const startHold = (id: string) => {
372	    hold.current = window.setTimeout(() => setDragging(id), 200);
