38	export function Discover() {
39	  const { user } = useAuth();
40	  const { profile } = usePrefs();
41	  const [query, setQuery] = useState('');
42	  const [results, setResults] = useState<GlossaryEntry[]>([]);
43	  const [loading, setLoading] = useState(true);
44	  const [inStackIds, setInStackIds] = useState<Set<string>>(new Set());
45	  const [addingIds, setAddingIds] = useState<Set<string>>(new Set());
46	  const [detailEntry, setDetailEntry] = useState<GlossaryEntry | null>(null);
47	  const [schedulingEntry, setSchedulingEntry] = useState<GlossaryEntry | null>(null);
48	  const [synonyms, setSynonyms] = useState<GoalSynonym[]>([]);
49	  const [refs, setRefs] = useState<Record<string, NutrientReference[]>>({});
50	  /** one row open at a time; its card renders underneath it */
51	  const [expandedId, setExpandedId] = useState<string | null>(null);
52	  /** set when a product's Ask a question button is pressed */
53	  const [askSeed, setAskSeed] = useState<string | null>(null);
54	  const [goAsk, setGoAsk] = useState(0);
55	
56	  useEffect(() => {
57	    getGoalSynonyms().then(setSynonyms);
58	  }, []);
59	
60	  useEffect(() => {
61	    setLoading(true);
62	    const handle = setTimeout(() => {
63	      // 200 rather than the default 8 — the list is the whole library now
64	      const fetcher = query.trim() ? matchGoal(query.trim()) : listGlossary(200);
65	      fetcher.then((r) => {
66	        setResults(r);
67	        setLoading(false);
68	      });
69	    }, 350);
70	    return () => clearTimeout(handle);
71	  }, [query]);
72	
73	  useEffect(() => {
74	    if (results.length === 0) return;
75	    getNutrientReference(results.map((r) => r.id)).then((m) =>
76	      setRefs((prev) => ({ ...prev, ...m })),
77	    );
78	  }, [results]);
79	
80	  useEffect(() => {
81	    if (!user || results.length === 0) {
82	      setInStackIds(new Set());
83	      return;
84	    }
85	    getStackMembership(
86	      user.id,
87	      results.map((r) => r.id),
88	    ).then(setInStackIds);
89	  }, [results, user?.id]);
90	
