import { useEffect, useState } from 'react';
import { Sheet } from '../components/Sheet';
import { Tabs } from '../components/Tabs';
import { GlossaryDetail } from './GlossaryDetail';
import { AddSchedule } from './AddSchedule';
import { ProductRow } from './DiscoverList';
import { AskAI } from './AskAI';
import { useAuth } from '../lib/auth';
import { usePrefs } from '../lib/prefs';
import {
  addToStack,
  getGoalSynonyms,
  getNutrientReference,
  getStackMembership,
  listGlossary,
  matchGoal,
  type GlossaryEntry,
  type GoalSynonym,
  type NutrientReference,
} from '../lib/api';
import { computeMatchReason } from '../lib/matchReason';
import { IconMenu, IconSearch } from '../components/Icons';

const CATEGORY_LABEL: Record<string, string> = {
  healing: 'Healing',
  growth: 'Growth',
  cosmetic: 'Cosmetic',
  cognitive: 'Cognitive',
  other: 'Other',
};

const TABS = [
  { id: 'ask', label: 'Ask AI' },
  { id: 'peptide', label: 'Peptides' },
  { id: 'supplement', label: 'Vitamins & Minerals' },
];

export function Discover() {
  const { user } = useAuth();
  const { profile } = usePrefs();
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<GlossaryEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [inStackIds, setInStackIds] = useState<Set<string>>(new Set());
  const [addingIds, setAddingIds] = useState<Set<string>>(new Set());
  const [detailEntry, setDetailEntry] = useState<GlossaryEntry | null>(null);
  const [schedulingEntry, setSchedulingEntry] = useState<GlossaryEntry | null>(null);
  const [synonyms, setSynonyms] = useState<GoalSynonym[]>([]);
  const [refs, setRefs] = useState<Record<string, NutrientReference[]>>({});
  /** one row open at a time; its card renders underneath it */
  const [expandedId, setExpandedId] = useState<string | null>(null);
  /** set when a product's Ask a question button is pressed */
  const [askSeed, setAskSeed] = useState<string | null>(null);
  const [goAsk, setGoAsk] = useState(0);

  useEffect(() => {
    getGoalSynonyms().then(setSynonyms);
  }, []);

  useEffect(() => {
    setLoading(true);
    const handle = setTimeout(() => {
      // 200 rather than the default 8 — the list is the whole library now
      const fetcher = query.trim() ? matchGoal(query.trim()) : listGlossary(200);
      fetcher.then((r) => {
        setResults(r);
        setLoading(false);
      });
    }, 350);
    return () => clearTimeout(handle);
  }, [query]);

  useEffect(() => {
    if (results.length === 0) return;
    getNutrientReference(results.map((r) => r.id)).then((m) =>
      setRefs((prev) => ({ ...prev, ...m })),
    );
  }, [results]);

  useEffect(() => {
    if (!user || results.length === 0) {
      setInStackIds(new Set());
      return;
    }
    getStackMembership(
      user.id,
      results.map((r) => r.id),
    ).then(setInStackIds);
  }, [results, user?.id]);

  const handleAddToStack = async (entry: GlossaryEntry) => {
    if (!user || inStackIds.has(entry.id) || addingIds.has(entry.id)) return;
    setAddingIds((prev) => new Set(prev).add(entry.id));
    try {
      await addToStack(user.id, entry.id);
      setInStackIds((prev) => new Set(prev).add(entry.id));
      /* Peptides go in the stack as a reference, never onto a schedule with an
         amount attached — the same split the tabs exist to express. */
      if ((entry.kind ?? 'peptide') === 'supplement') setSchedulingEntry(entry);
    } finally {
      setAddingIds((prev) => {
        const next = new Set(prev);
        next.delete(entry.id);
        return next;
      });
    }
  };

  const top = results[0] ?? null;
  const topReason = top ? computeMatchReason(top, query, synonyms) : null;
  const detailReason = detailEntry ? computeMatchReason(detailEntry, query, synonyms) : null;

  return (
    <>
      <div className="screen-head">
        <h1 className="t-title">Discover</h1>
        <div className="screen-sub t-body">Glossary · Research</div>
      </div>

      <Tabs
        tabs={TABS}
        storageKey="pepstack.discover.tab"
        defaultId="supplement"
        jumpTo={goAsk}
        jumpToIndex={0}
      >
        {(tab) => {
          if (tab.id === 'ask') {
            return <AskAI seed={askSeed} onSeedUsed={() => setAskSeed(null)} />;
          }

          /* Nothing carried a kind before migration 0016, so an unset value
             reads as a peptide — which is what every earlier entry is. */
          const shown = results.filter((r) => (r.kind ?? 'peptide') === tab.id);

          return (
            <div>
              {tab.id === 'peptide' && (
                <p className="tab-note t-caption">
                  Reference only. These are not over-the-counter supplements and Pepstack does not
                  recommend doses for them.
                </p>
              )}

              {/* Free-text match against the existing catalogue (lib/api matchGoal).
                  Never a generated answer — always a filtered list of real entries. */}
              <div className="search">
                <span style={{ color: 'var(--t3)', display: 'flex' }}>
                  <IconMenu />
                </span>
                <input
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  placeholder="Search a product, or describe your goal"
                  spellCheck={false}
                />
                <span style={{ color: 'var(--t3)', display: 'flex' }}>
                  <IconSearch />
                </span>
              </div>

              {topReason && query.trim() && (
                <div className="match-context t-caption" style={{ marginTop: 10 }}>
                  {topReason.type === 'keyword'
                    ? `Matched "${query.trim()}" via: "${topReason.keyword}"`
                    : `Understood "${query.trim()}" as related to: ${topReason.tags
                        .map((t) => CATEGORY_LABEL[t] ?? t)
                        .join(', ')}`}
                </div>
              )}

              {loading && (
                <div className="empty-state t-body" style={{ marginTop: 24 }}>
                  Loading…
                </div>
              )}

              {!loading && shown.length === 0 && (
                <div className="empty-state t-body" style={{ marginTop: 24 }}>
                  {query.trim() ? `Nothing here matches "${query.trim()}" yet.` : 'Nothing here yet.'}
                </div>
              )}

              <div className="prod-list">
                <span className="rail" />
                {shown.map((r) => (
                  <ProductRow
                    key={r.id}
                    entry={r}
                    refs={refs[r.id]}
                    age={profile?.age}
                    sex={profile?.sex}
                    inStack={inStackIds.has(r.id)}
                    adding={addingIds.has(r.id)}
                    expanded={expandedId === r.id}
                    onToggle={() => setExpandedId((id) => (id === r.id ? null : r.id))}
                    onAdd={() => handleAddToStack(r)}
                    onAsk={() => {
                      setAskSeed(`I have a question about ${r.name}. `);
                      setGoAsk((n) => n + 1);
                    }}
                    onAllArticles={() => setDetailEntry(r)}
                  />
                ))}
              </div>
            </div>
          );
        }}
      </Tabs>

      <Sheet open={!!detailEntry} onClose={() => setDetailEntry(null)} title={detailEntry?.name ?? ''}>
        {detailEntry && (
          <GlossaryDetail
            entry={detailEntry}
            matchContext={detailReason ? { query: query.trim(), reason: detailReason } : undefined}
          />
        )}
      </Sheet>

      <Sheet open={!!schedulingEntry} onClose={() => setSchedulingEntry(null)} title="Add to Schedule">
        {schedulingEntry && user && (
          <AddSchedule
            userId={user.id}
            glossaryId={schedulingEntry.id}
            defaultName={schedulingEntry.name}
            onAdded={() => setSchedulingEntry(null)}
            onClose={() => setSchedulingEntry(null)}
          />
        )}
      </Sheet>
    </>
  );
}

 * Slugs are matched as well as names so this survives item 0.5 renaming them
 * from ingredient-shaped to `<brand>-<product>` — both shapes contain the
 * ingredient.
 */
const textOf = (e: GlossaryEntry) =>
  `${e.name} ${e.slug} ${(e.search_keywords ?? []).join(' ')}`.toLowerCase();

const hits = (text: string, terms: readonly RegExp[]) => terms.some((t) => t.test(text));

/**
 * Word-bounded, so "iron" does not match inside another word and "niacin"
 * does not match "niacinamide" — the two forms of B3 are the whole point of
 * one of the rules below and must stay distinguishable.
 */
const NUTRIENT = {
  b12: [/\bb-?12\b/, /cobalamin/],
  iron: [/\biron\b/, /ferrous/, /ferric/],
  zinc: [/\bzinc\b/],
  magnesium: [/\bmagnesium\b/],
  omega3: [/\bomega[\s-]?3\b/, /\bdha\b/, /\bepa\b/, /fish oil/, /\bkrill\b/, /cod liver/],
  calcium: [/\bcalcium\b/],
  vitaminD: [/\bvitamin\s?d\b/, /\bd-?3\b/, /cholecalciferol/],
  // choline bitartrate and anything else that names choline. Citicoline and
  // alpha-GPC raise choline too but spell neither, and they are catalogued as
  // cognitive products — left out rather than quietly folded in.
  choline: [/choline/],
  niacin: [/niacin/, /nicotinamide/, /nicotinic/],
} as const;

/* ── product form ────────────────────────────────────────────────────── */

export type FormClass = 'capsule' | 'softgel' | 'tablet' | 'powder' | 'liquid' | 'gummy' | 'other';

/**
 * DSLD writes softgels as "Softgel Capsule", so softgel has to be tested
 * before capsule or every softgel in the library reads as a capsule.
 */
export function classifyForm(productForm: string | null | undefined): FormClass {
  const f = (productForm ?? '').toLowerCase();
  if (!f) return 'other';
  if (f.includes('gummy') || f.includes('gummies') || f.includes('chew')) return 'gummy';
  if (f.includes('softgel') || f.includes('soft gel')) return 'softgel';
  if (f.includes('capsule')) return 'capsule';
  if (f.includes('tablet') || f.includes('caplet')) return 'tablet';
  if (f.includes('powder')) return 'powder';
  if (f.includes('liquid') || f.includes('drops') || f.includes('tincture') || f.includes('oil'))
    return 'liquid';
  return 'other';
}

/** The onboarding option ids, in the same order as the question. */
const FORM_OPTION: Record<string, FormClass> = {
  capsule: 'capsule',
  tablet: 'tablet',
  softgel: 'softgel',
  powder: 'powder',
  liquid: 'liquid',
  gummy: 'gummy',
};

const FORM_PLURAL: Record<FormClass, string> = {
  capsule: 'capsules',
  softgel: 'softgels',
  tablet: 'tablets',
  powder: 'powders',
  liquid: 'liquids',
  gummy: 'gummies',
  other: 'this form',
};

/** A softgel is a capsule as far as swallowing one goes. */
const HARD_TO_SWALLOW: FormClass[] = ['capsule', 'softgel', 'tablet'];
const EASY_TO_SWALLOW: FormClass[] = ['powder', 'liquid'];

/* ── the diet table (spec 2.1) ───────────────────────────────────────── */

interface PriorityRule {
  /** the diet id that turns it on */
  when: string;
  group: readonly RegExp[];
  reason: string;
  /**
   * Pushes to the top of the list whatever the goals were, and keeps the
   * entry even when it matched no goal at all. Only B12 earns this.
   */
  required?: boolean;
  /** multiplier on the reference intake, where the published one differs */
  amountFactor?: number;
}

const DIET_RULES: PriorityRule[] = [
  {
    when: 'no-meat',
    group: NUTRIENT.b12,
    required: true,
    reason: 'You said no meat — this is the one thing with no reliable plant source.',
  },
  {
    when: 'no-meat',
    group: NUTRIENT.iron,
    // NIH ODS: the recommended intake for vegetarians is 1.8× the RDA, because
    // non-haem iron absorbs far less well than the haem kind.
    amountFactor: 1.8,
    reason: 'Vegetarian iron targets are 1.8× the standard, because non-haem iron absorbs less well.',
  },
  {
    when: 'no-meat',
    group: NUTRIENT.zinc,
    reason: 'Phytate in grains and legumes binds zinc, so vegetarians can need up to 50% more.',
  },
  {
    when: 'no-dairy',
    group: NUTRIENT.calcium,
    reason: 'You said no dairy, which is where most people get most of their calcium.',
  },
  {
    when: 'no-dairy',
    group: NUTRIENT.vitaminD,
    reason: 'You said no dairy — fortified milk is one of the few food sources of vitamin D.',
  },
  {
    when: 'no-eggs',
    group: NUTRIENT.choline,
    reason: 'You said no eggs, which are the densest food source of choline.',
  },
];

/* ── the swap table (spec 2.1 omega-3, 2.2 reactions) ────────────────── */

interface SwapRule {

