/* ============================================================
   Halfpast — design tokens. Nothing outside this block defines
   a colour. Elevation is opaque steps, never 1px hairlines.
   ============================================================ */
:root {
  --bg: #000000;
  --card: #16161a;
  --card-hi: #1e1e22;
  /* the Discover result card sits one step above --card in the export */
  --card-2: #252529;
  --purple: #7b5cfa;
  --purple-dim: rgba(123, 92, 250, 0.35);

  /* Glass, measured off the exports rather than guessed. The fill is a barely
     there white over black; the read comes almost entirely from the rim, which
     is directional — bright along the top and left, faint along the bottom,
     absent on the right. That is a lit edge, not a uniform hairline. */
  --glass: rgba(255, 255, 255, 0.022);
  --rim-hi: rgba(255, 255, 255, 0.36);
  --rim-lo: rgba(255, 255, 255, 0.07);
  /* The pill reads as translucent purple but cannot be: it is greener-poor
     than the bar underneath, so no alpha over --card reaches it. These are the
     two ends of the gradient the export actually paints. */
  --pill-1: #181130;
  --pill-2: #272042;
  --scrim: rgba(0, 0, 0, 0.55);
  --danger: #ff6b6b;
  --danger-dim: rgba(255, 107, 107, 0.55);
  --pill-rim-hi: rgba(255, 255, 255, 0.4);
  --pill-rim-lo: rgba(255, 255, 255, 0.09);

  --t1: rgba(255, 255, 255, 1);
  --t2: rgba(255, 255, 255, 0.62);
  --t3: rgba(255, 255, 255, 0.38);
  --t4: rgba(255, 255, 255, 0.22);

  /* the arc's unfilled segments — an opaque step, not a white alpha */
  --track: #252528;
  /* the calendar's empty cell */
  --cell-empty: #0e0e11;

  --margin: 20px;
  --tab-h: 48px;

  /* Larger Text multiplies this rather than zooming the layout — zoom
     scales the whole box model (including the fixed 402x874 desktop
     preview frame and its overflow:hidden clip), which pushed real
     content outside the clip and broke hit-testing on real buttons. */
  --text-scale: 1;

  color-scheme: dark;
}
.app.larger-text {
  --text-scale: 1.14;
}

/* One material, used wherever the export shows one. */
.glass {
  background: var(--glass);
  box-shadow:
    inset 1px 1px 0 var(--rim-hi),
    inset -1px -1px 0 var(--rim-lo);
}

/* ── the four tells that scream "website" ── */
* {
  -webkit-tap-highlight-color: transparent;
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--t1);
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: manipulation;
  -webkit-font-smoothing: antialiased;
  /* -apple-system resolves to real SF Pro on device — that is most of the
     native read. Inter is only the desktop fallback, never fetched. */
  font-family: -apple-system, 'SF Pro Text', 'SF Pro Display', Inter, system-ui, sans-serif;
}

h1,
h2,
h3,
p {
  margin: 0;
  font-weight: inherit;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
}

/* ============================================================
   Type scale
   ============================================================ */
.t-title {
  font-size: calc(33px * var(--text-scale));
  font-weight: 700;
  letter-spacing: -1px;
  line-height: calc(38px * var(--text-scale));
}
.t-big {
  font-size: calc(44px * var(--text-scale));
  font-weight: 700;
  letter-spacing: -1.5px;
  line-height: 1;
}
.t-section {
  font-size: calc(17px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.45px;
}
.t-body {
  font-size: calc(15px * var(--text-scale));
  font-weight: 400;
  letter-spacing: -0.1px;
}
.t-body-m {
  font-size: calc(15px * var(--text-scale));
  font-weight: 500;
  letter-spacing: -0.1px;
}
.t-secondary {
  font-size: calc(13px * var(--text-scale));
  font-weight: 400;
  letter-spacing: 0;
}
.t-caption {
  font-size: calc(12px * var(--text-scale));
  font-weight: 400;
  letter-spacing: 0;
}
.t-label {
  font-size: calc(10.5px * var(--text-scale));
  font-weight: 600;
  letter-spacing: 1.1px;
  text-transform: uppercase;
}

/* ============================================================
   App shell
   ============================================================ */
.app {
  position: relative;
  width: 100%;
  height: 100dvh; /* never vh — Safari's collapsing toolbar clips the bottom */
  overflow: hidden;
  background: var(--bg);
}

/* Desktop preview only: a phone-shaped box. On a real device the app is
   the viewport and this never applies. */
.frame-host {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: var(--card);
}
.frame {
  position: relative;
  width: 402px;
  height: 874px;
  overflow: hidden;
  border-radius: 44px;
  background: var(--bg);
  flex: none;
  /* a transform makes this the containing block for position:fixed
     descendants (the Sheet overlay) — without it, fixed elements anchor
     to the real browser viewport instead of this phone-mockup box. */
  transform: translateZ(0);
}

.status {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 54px;
  padding: 0 var(--margin);
  padding-top: env(safe-area-inset-top);
  display: flex;
  align-items: center;
  z-index: 8;
  pointer-events: none;
}
.status span {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.2px;
}

/* ── the horizontal page controller ── */
.track {
  position: absolute;
  inset: 0;
  display: flex;
  width: 300%;
  will-change: transform;
}
.panel {
  width: 33.3333%;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  padding: 0 var(--margin);
  /* On a device the status bar is the OS's (standalone) or Safari's (browser),
     and the inset already accounts for it. Only the desktop phone-box draws a
     fake one, and only there does the 54px band exist. */
  padding-top: env(safe-area-inset-top);
  padding-bottom: calc(var(--tab-h) + 34px + env(safe-area-inset-bottom));
}
.app.framed .panel {
  padding-top: 54px;
}
.panel::-webkit-scrollbar {
  width: 0;
  height: 0;
}

/* ============================================================
   Press states — a row that does nothing until you lift feels dead
   ============================================================ */
.pressable {
  transition:
    background-color 90ms ease-out,
    transform 90ms ease-out;
}
.pressable:active {
  background-color: var(--card-hi);
  transform: scale(0.985);
}

/* ============================================================
   Tab bar
   ============================================================ */
.bar {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 232px;
  bottom: max(34px, calc(12px + env(safe-area-inset-bottom)));
  height: var(--tab-h);
  border-radius: 24px;
  background: var(--card);
  padding: 7px;
  z-index: 20;
  display: block;
  /* the bar owns its own gesture — the browser must not pan or scroll on it */
  touch-action: none;
}
.bar-inner {
  position: relative;
  height: 100%;
}
.pill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  border-radius: 17px;
  /* glass, lit from the top-left, exactly as the export renders it */
  background: linear-gradient(160deg, var(--pill-1), var(--pill-2));
  will-change: transform, width;
  pointer-events: none;
}
.tab {
  position: absolute;
  top: 0;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  overflow: hidden;
  white-space: nowrap;
  z-index: 1;
}
.tab-icon {
  flex: none;
  display: grid;
  place-items: center;
  will-change: transform;
}
.tab-label {
  font-size: calc(14px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.2px;
  color: var(--t1);
  overflow: hidden;
  will-change: opacity, transform, width;
}
/* offscreen measurement copy — never visible, never interactive */
.tab-measure {
  position: absolute;
  visibility: hidden;
  pointer-events: none;
  white-space: nowrap;
  font-size: calc(14px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.2px;
  top: -9999px;
  left: -9999px;
}

/* ============================================================
   Today
   ============================================================ */
.screen-head {
  padding-top: 18px;
}
.screen-sub {
  margin-top: 6px;
  line-height: calc(20px * var(--text-scale));
  color: var(--t2);
}

.week {
  display: flex;
  gap: 9px;
  margin-top: 22px;
}
.week-cell {
  flex: 1;
  height: 62px;
  border-radius: 15px;
  background: var(--card);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  position: relative;
}
.week-cell.today {
  background: var(--purple);
}
.week-dow {
  font-size: calc(11px * var(--text-scale));
  font-weight: 500;
  color: var(--t3);
}
.week-cell.today .week-dow {
  color: var(--t2);
}
.week-num {
  font-size: calc(17px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.45px;
}
.week-cell.today .week-num {
  color: #fff;
}
.week-cell.missed .week-num {
  color: var(--t3);
}
/* days that have not happened yet are glass, not a filled card */
.week-cell.future {
  background: var(--glass);
  box-shadow:
    inset 1px 1px 0 var(--rim-hi),
    inset -1px -1px 0 var(--rim-lo);
}
.week-cell.future .week-num,
.week-cell.future .week-dow {
  color: var(--t4);
}
/* one property means one thing: the dot means completed, nothing else */
.week-dot {
  position: absolute;
  bottom: 8px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--purple);
}

.arc-wrap {
  position: relative;
  height: 95px;
  width: 368px;
  /* the artwork runs 3px past the 20px margin on each side */
  margin: 32px -3px 0;
}
.arc-wrap svg {
  display: block;
}
.arc-ends {
  position: absolute;
  top: 77px;
  left: -8px;
  right: -9px;
  display: flex;
  justify-content: space-between;
  color: var(--t3);
  font-size: calc(13px * var(--text-scale));
}
.arc-centre {
  position: absolute;
  top: 18px;
  left: 0;
  right: 0;
  text-align: center;
}
.arc-count {
  font-size: calc(44px * var(--text-scale));
  font-weight: 700;
  letter-spacing: -1.5px;
  line-height: 1;
}
.arc-left {
  margin-top: -1px;
  color: var(--t2);
  font-size: calc(13px * var(--text-scale));
}

.divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 31px;
}
.divider-line {
  flex: 1;
  height: 2px;
  border-radius: 1px;
  background: var(--card-hi);
}
.divider-text {
  color: var(--t3);
}

.timeline {
  position: relative;
  margin-top: 13px;
  padding-left: 22px;
  padding-right: 10px;
}
.rail {
  position: absolute;
  left: 3px;
  top: 15px;
  bottom: 8px;
  width: 2px;
  border-radius: 1px;
  background: var(--t1);
}
.dose {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border-radius: 18px;
  height: 64px;
  padding: 0 16px;
  margin-bottom: 8px;
}
.dose:last-child {
  margin-bottom: 0;
}
.dose {
  -webkit-touch-callout: none;
  transition:
    transform 180ms ease-out,
    background-color 180ms ease-out;
}
/* the row sinks while held, so the press reads as going somewhere */
.dose.holding {
  transform: scale(0.975);
  background-color: var(--card-hi);
}
.dose.holding.taken {
  background-color: var(--card-hi);
}
@media (prefers-reduced-motion: reduce) {
  .dose,
  .dose-mark {
    transition: none;
  }
  .dose.holding {
    transform: none;
  }
}
/* the dose already taken is glass — the two still to come are solid */
.dose.taken {
  background: var(--glass);
  box-shadow:
    inset 1px 1px 0 var(--rim-hi),
    inset -1px -1px 0 var(--rim-lo);
}
.dose-time {
  width: 61px;
  flex: none;
  color: var(--t3);
  font-size: calc(13px * var(--text-scale));
}
.dose-body {
  flex: 1;
  min-width: 0;
}
.dose-name {
  font-size: calc(15px * var(--text-scale));
  line-height: calc(18px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}
.dose.taken .dose-name {
  color: var(--t2);
}
.dose-amt {
  margin-top: 3px;
  font-size: calc(12px * var(--text-scale));
  line-height: calc(14px * var(--text-scale));
  color: var(--t3);
}
.dose-mark {
  position: relative;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  flex: none;
  transition: transform 120ms ease-out;
}
/* 24px is the drawn size; the tap target is the full 44 */
.dose-mark::after {
  content: '';
  position: absolute;
  inset: -10px;
}
.dose-mark:active {
  transform: scale(0.88);
}
.dose-mark.on {
  background: var(--purple);
}
.dose-mark.off {
  box-shadow: inset 0 0 0 1.5px var(--t4);
}

.warn {
  margin-top: 31px;
  color: var(--purple);
  font-size: calc(12px * var(--text-scale));
  line-height: calc(15px * var(--text-scale));
  text-align: left;
}

/* ============================================================
   Discover
   ============================================================ */
.search {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 46px;
  border-radius: 14px;
  background: var(--card);
  padding: 0 14px;
  margin-top: 20px;
}
.search input {
  flex: 1;
  min-width: 0;
  background: none;
  border: 0;
  outline: none;
  color: var(--t1);
  font-size: calc(15px * var(--text-scale));
  letter-spacing: -0.1px;
}
.search input::placeholder {
  color: var(--t3);
}

.match-context {
  color: var(--t3);
  line-height: 1.4;
}

.result {
  /* the card is inset a further 8px inside the 20px margin */
  margin: 27px 8px 0;
  background: var(--card-2);
  border-radius: 22px;
  padding: 15px 15px 9px;
}
.result-title {
  line-height: calc(18px * var(--text-scale));
  color: var(--purple);
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}
/* placeholder for a paper thumbnail — --card, never white */
.thumb {
  margin-top: 6px;
  height: 215px;
  border-radius: 15px;
  background: var(--card-hi);
  display: grid;
  place-items: center;
}
.result-actions {
  display: flex;
  gap: 10px;
  margin-top: 13px;
}
/* the only row that shares width between two buttons */
.result-actions .btn {
  flex: 1;
  min-width: 0;
}
/* NOT flex: 1. This button is used inside column flex containers (.auth-form,
   the sheets), where flex:1 resolves flex-basis:0 against the VERTICAL axis and
   silently overrides the height — every button in a form collapsed to ~20px.
   The one place it needs to share a row scopes it below. */
.btn {
  flex: none;
  height: 56px;
  min-height: 56px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}
.btn-fill {
  background: var(--purple);
  color: #000;
}
.btn-out {
  box-shadow: inset 0 0 0 1.5px var(--purple);
  color: var(--purple);
}

.papers {
  position: relative;
  margin-top: 12px;
  padding-left: 22px;
}
.paper {
  height: 54px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.paper-title {
  line-height: calc(18px * var(--text-scale));
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}
.paper-meta {
  margin-top: 4px;
  line-height: calc(14px * var(--text-scale));
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--t3);
  font-size: calc(12px * var(--text-scale));
}
.paper-add {
  margin-left: auto;
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 11px;
  background: var(--card-hi);
  color: var(--t2);
  display: grid;
  place-items: center;
}
.paper-add:disabled {
  opacity: 0.7;
}
.paper-more {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--purple);
  font-size: calc(12px * var(--text-scale));
}

/* ============================================================
   You
   ============================================================ */
.streak {
  margin-top: 8px;
  line-height: calc(20px * var(--text-scale));
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--purple);
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}

.widgets {
  display: flex;
  gap: 12px;
  /* the pair runs 6px wider than the margin on each side in the export */
  margin: 19px -6px 0;
}
.widget {
  width: 181px;
  height: 176px;
  border-radius: 22px;
  background: var(--card);
  flex: none;
  padding: 12px;
  overflow: hidden;
  /* the calendar below takes whatever height is left, rather than assuming
     a row count and spilling past the corner when the month needs six */
  display: flex;
  flex-direction: column;
}
.widget-num {
  text-align: center;
  color: var(--purple);
  font-size: calc(44px * var(--text-scale));
  font-weight: 700;
  letter-spacing: -1.5px;
  line-height: 1;
}
/* One grid: a weekday header row, then one row per week of THIS month.
   --cal-rows comes from the data, and every row is 1fr, so a 4-row February
   and a 6-row month both land inside the widget instead of overflowing it. */
.cal {
  margin-top: 8px;
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: 13px repeat(7, minmax(0, 1fr));
  grid-template-rows: 12px repeat(var(--cal-rows, 5), minmax(0, 1fr));
  gap: 3px 4px;
}
.cal-week-label {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  color: var(--t3);
  font-size: calc(9px * var(--text-scale));
  line-height: 1;
}
.cal-dow {
  text-align: center;
  color: var(--t3);
  font-size: calc(10px * var(--text-scale));
  line-height: 12px;
}
.cal-cell {
  min-height: 0;
  border-radius: 4px;
  background: var(--cell-empty);
}
.cal-cell.on {
  background: var(--purple);
}
/* today reads as an outline, so it stacks with .on rather than fighting it */
.cal-cell.today {
  box-shadow: inset 0 0 0 1.5px var(--purple);
}
/* the days before the 1st and after the last: space, not a square */
.cal-corner,
.cal-blank {
  background: none;
}

/* an intentionally empty box — the label names what belongs here */
.widget-gap {
  display: grid;
  place-items: center;
  text-align: center;
  padding: 18px;
}
.widget-gap span {
  color: var(--t3);
  font-size: calc(12px * var(--text-scale));
  line-height: 1.4;
}

.rows {
  margin-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.row {
  display: flex;
  align-items: center;
  height: 48px;
  padding: 0 16px;
  border-radius: 16px;
  background: var(--card);
}
.row-label {
  flex: 1;
  font-size: calc(15px * var(--text-scale));
  font-weight: 500;
  letter-spacing: -0.1px;
}
.row-value {
  color: var(--t3);
  font-size: calc(13px * var(--text-scale));
}

/* ============================================================
   Loading splash
   ============================================================ */
.splash {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ============================================================
   Auth
   ============================================================ */
.auth-panel {
  /* deliberately not `.panel` — that class is 33.3333% wide, sized for the
     three-way pager inside `.track`; reused bare here it squeezed the whole
     screen into a third of the frame's width. */
  width: 100%;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  padding: 0 var(--margin);
  padding-top: env(safe-area-inset-top);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-bottom: env(safe-area-inset-bottom);
}
.app.framed .auth-panel {
  padding-top: 54px;
}
.auth-screen {
  width: 100%;
}
.auth-head {
  margin-bottom: 28px;
}
.auth-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.field-row {
  display: flex;
  gap: 12px;
}
.stack-pick-row {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 2px;
  -webkit-overflow-scrolling: touch;
}
.stack-pick-row::-webkit-scrollbar {
  display: none;
}
.stack-pick-chip {
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 38px;
  padding: 0 16px;
  border-radius: 15px;
  background: var(--card);
  color: var(--t2);
  font-size: calc(13px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
  white-space: nowrap;
}
.stack-pick-chip.active {
  background: var(--purple);
  color: var(--bg);
}
.field .t-label {
  color: var(--t3);
}
.field-input {
  min-height: 52px;
  height: 46px;
  border-radius: 14px;
  background: var(--card);
  border: 0;
  outline: none;
  padding: 0 14px;
  color: var(--t1);
  font-size: calc(15px * var(--text-scale));
  letter-spacing: -0.1px;
  font-family: inherit;
  -webkit-user-select: text;
  user-select: text;
}
.field-input::placeholder {
  color: var(--t3);
}
.auth-error {
  color: #ff6b6b;
}
.auth-switch {
  margin-top: 20px;
  text-align: center;
  width: 100%;
  color: var(--t2);
  font-size: calc(13px * var(--text-scale));
}

/* ============================================================
   Sheet — the one sanctioned pattern for secondary screens
   ============================================================ */
.sheet-backdrop {
  position: fixed;
  inset: 0;
  background: var(--scrim);
  z-index: 40;
}
.sheet {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  max-height: 82%;
  background: var(--card);
  border-radius: 26px 26px 0 0;
  z-index: 41;
  display: flex;
  flex-direction: column;
  padding-bottom: calc(20px + env(safe-area-inset-bottom));
}
.sheet-handle {
  width: 36px;
  height: 4px;
  border-radius: 2px;
  background: var(--t4);
  margin: 10px auto 0;
  flex: none;
}
.sheet-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px var(--margin) 4px;
  flex: none;
}
.sheet-close {
  width: 30px;
  height: 30px;
  border-radius: 15px;
  background: var(--card-hi);
  display: grid;
  place-items: center;
}
.sheet-body {
  padding: 14px var(--margin) 4px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.sheet-empty {
  color: var(--t3);
  padding: 24px 0;
  text-align: center;
}

/* ============================================================
   Today — add dose / history / empty state
   ============================================================ */
.empty-state {
  color: var(--t3);
  padding: 18px 4px;
}
.add-dose {
  flex: none;
  margin-top: 12px;
  height: 56px;
  min-height: 56px;
  width: 100%;
  border-radius: 16px;
  box-shadow: inset 0 0 0 1.5px var(--purple);
  color: var(--purple);
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
}
.action-row {
  display: flex;
  gap: 10px;
}
.action-row .add-dose {
  flex: 1;
  min-width: 0;
}
.history-summary {
  color: var(--t2);
  margin-bottom: 12px;
}
.schedule-remove-btn {
  flex: none;
  width: 100%;
  height: 52px;
  min-height: 52px;
  border-radius: 16px;
  box-shadow: inset 0 0 0 1.5px var(--danger-dim);
  color: var(--danger);
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
  margin-bottom: 16px;
}
.history-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.history-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--card-hi);
  border-radius: 15px;
  padding: 10px 14px;
}
.history-meta {
  color: var(--t3);
  margin-top: 2px;
}

/* ============================================================
   Discover — glossary detail sheet
   ============================================================ */
.glossary-tags {
  display: flex;
  gap: 8px;
  margin-bottom: 4px;
}
.tag {
  padding: 5px 10px;
  border-radius: 10px;
  background: var(--card-hi);
  color: var(--t2);
  font-size: calc(12px * var(--text-scale));
  font-weight: 600;
}
.glossary-field {
  margin-top: 16px;
}
.research-link {
  display: flex;
  align-items: center;
  min-height: 44px;
  padding: 11px 0;
  box-shadow: inset 0 1.5px 0 var(--card-hi);
  color: var(--t1);
}
.research-link:first-child {
  box-shadow: none;
}

/* ============================================================
   My Stack
   ============================================================ */
.stack-list {
  margin-top: 13px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.stack-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--card);
  border-radius: 16px;
  min-height: 56px;
  padding: 10px 12px;
}
.stack-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.stack-vial {
  color: var(--purple);
}
.stack-name {
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stack-meta {
  color: var(--t3);
}
.expiry-badge.soon {
  color: var(--purple);
}
.expiry-badge.expired {
  color: #ff6b6b;
}
.stack-expiry-btn {
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 32px;
  padding: 0 10px;
  border-radius: 10px;
  background: var(--card-hi);
  color: var(--t2);
  font-weight: 600;
  font-size: calc(12px * var(--text-scale));
}
.stack-remove {
  flex: none;
  width: 34px;
  height: 34px;
  border-radius: 17px;
  background: var(--card-hi);
  display: grid;
  place-items: center;
}

/* ============================================================
   Progress notes
   ============================================================ */
.progress-list {
  margin-top: 13px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.progress-row {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border-radius: 16px;
  padding: 10px 12px;
}
.progress-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.note-thumb {
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: var(--card-hi);
  object-fit: cover;
}
.note-thumb-empty {
  display: grid;
  place-items: center;
}
.field-file {
  color: var(--t2);
  font-size: calc(13px * var(--text-scale));
}

/* ============================================================
   Reconstitution calculator
   ============================================================ */
.recon-input-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.recon-input-row .field-input {
  flex: 1;
}
.recon-unit {
  flex: none;
  color: var(--t3);
  font-size: calc(14px * var(--text-scale));
  font-weight: 600;
  width: 34px;
}
.recon-unit-toggle {
  flex: none;
  display: flex;
  background: var(--card);
  border-radius: 12px;
  padding: 3px;
  gap: 3px;
}
.recon-unit-btn {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 16px;
  border-radius: 12px;
  color: var(--t3);
  font-size: calc(13px * var(--text-scale));
  font-weight: 600;
}
.recon-unit-btn.active {
  background: var(--purple);
  color: var(--bg);
}
.recon-result {
  margin-top: 20px;
  background: var(--card);
  border-radius: 16px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.recon-result-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.recon-big {
  font-size: calc(20px * var(--text-scale));
  font-weight: 700;
  color: var(--purple);
  letter-spacing: -0.02em;
}

/* ============================================================
   Injection site body map
   ============================================================ */
.bodymap-card {
  margin-top: 13px;
  background: var(--card);
  border-radius: 18px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.bodymap-figure {
  width: 128px;
  height: 208px;
}
.bodymap-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}
.bodymap-chip {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 14px;
  border-radius: 12px;
  background: var(--card-hi);
  color: var(--t2);
  font-size: calc(12px * var(--text-scale));
  font-weight: 600;
}
.bodymap-chip.active {
  background: var(--purple);
  color: var(--bg);
}
.bodymap-detail {
  color: var(--t2);
  text-align: center;
}
.bodymap-detail strong {
  color: var(--t1);
  font-weight: 600;
}


/* ============================================================
   Setup screen — shown when the Supabase env vars are absent.
   Deliberately plain: it is a diagnostic, not part of the product.
   ============================================================ */
.setup {
  height: 100dvh;
  overflow-y: auto;
  background: var(--bg);
  padding: calc(env(safe-area-inset-top) + 32px) var(--margin) 40px;
}
.setup-inner {
  max-width: 420px;
  margin: 0 auto;
}
.setup-title {
  font-size: 27px;
  font-weight: 700;
  letter-spacing: -0.7px;
  line-height: 32px;
}
.setup-body {
  margin-top: 10px;
  color: var(--t2);
  font-size: 15px;
  line-height: 21px;
}
.setup-vars {
  margin-top: 20px;
  border-radius: 16px;
  background: var(--card);
  padding: 4px 14px;
}
.setup-var {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 40px;
  font-size: 13px;
}
.setup-var code {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
}
.setup-state {
  color: var(--t3);
  font-size: 12px;
}
.setup-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex: none;
}
.setup-dot.on {
  background: var(--purple);
}
.setup-dot.off {
  background: var(--t4);
}
.setup-steps {
  margin: 22px 0 0;
  padding-left: 20px;
  color: var(--t2);
  font-size: 14px;
  line-height: 21px;
}
.setup-steps li {
  margin-bottom: 12px;
}
.setup-steps b {
  color: var(--t1);
  font-weight: 600;
}
.setup-steps code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  color: var(--t1);
}

/* the form saying where a pre-filled value came from — it is always the
   user's own prior entry, never anything the app decided */
.prefill-note {
  margin-top: -6px;
  color: var(--t3);
  line-height: 16px;
}

/* the taken segment wipes on from the left — ease-in, so it starts slow */
.arc-fill {
  transition: stroke-dashoffset 620ms cubic-bezier(0.42, 0, 1, 1);
}
@media (prefers-reduced-motion: reduce) {
  .arc-fill {
    transition: none;  
  }
}

/* the preview box holds the first paper on file rather than a placeholder */
.thumb-paper {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 7px;
  padding: 20px 20px 18px;
  text-align: left;
  text-decoration: none;
  color: var(--t1);
}
.thumb-kicker {
  color: var(--t3);
}
.thumb-title {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.3px;
  line-height: 25px;
  /* long paper titles are normal; clamp rather than blow the box open */
  display: -webkit-box;
  -webkit-line-clamp: 5;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.thumb-meta {
  color: var(--t2);
}
.thumb-cta {
  margin-top: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--purple);
}

.result-kind {
  margin-top: 3px;
  color: var(--t3);
  text-transform: capitalize;
}

/* branded product header inside the detail sheet */
.glossary-brand {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 12px;
  color: var(--t3);
}
.glossary-brand-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--t2);
}
.glossary-brand-link {
  margin-left: auto;
  color: var(--purple);
  text-decoration: none;
  min-height: 32px;
  display: inline-flex;
  align-items: center;
}

/* ============================================================
   Discover tabs — segmented control over a swipeable pager
   ============================================================ */
.tabs {
  position: relative;
  margin-top: 18px;
  /* The track is three panels wide and was spilling past the panel's content
     box, so slivers of the neighbouring tabs showed down both edges. `clip`
     rather than `hidden`: hidden would make this a scroll container and break
     the sticky chat composer inside it. */
  overflow-x: clip;
}
.tabs-bar {
  position: relative;
  display: flex;
  gap: 22px;
  padding-bottom: 11px;
}
.tabs-tab {
  flex: none;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.2px;
  color: var(--t2);
  min-height: 34px;
  transition: color 180ms ease-out;
}
.tabs-tab.on {
  color: var(--t1);
}
.tabs-underline {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  border-radius: 1px;
  background: var(--purple);
  will-change: transform, width;
}
.tabs-track {
  display: flex;
  margin-top: 4px;
  will-change: transform;
}
.tabs-panel {
  flex: none;
  min-width: 0;
  /* the pager only translates; each panel scrolls with the page */
  padding-right: 0;
}
/* the peptide tab's standing caveat */
.tab-note {
  margin: 14px 0 2px;
  color: var(--t3);
  line-height: 1.45;
}
.evidence-chip {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 9px;
  border-radius: 999px;
  box-shadow: inset 0 0 0 1px var(--purple-dim);
  color: var(--purple);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.2px;
  text-transform: capitalize;
  flex: none;
}

/* ============================================================
   Discover — a flush list against a rail. A row only becomes a
   card once it is opened.
   ============================================================ */
.prod-list {
  position: relative;
  margin-top: 16px;
  padding-left: 22px;
}
/* the same white rail the paper list used */
.prod-list .rail {
  position: absolute;
  left: 3px;
  top: 6px;
  bottom: 6px;
  width: 2px;
  border-radius: 1px;
  background: var(--t1);
}
.prod {
  border-radius: 18px;
  background: none;
  transition:
    background-color 200ms ease-out,
    padding 200ms ease-out,
    margin 200ms ease-out;
}
/* only the open one is a card */
.prod.open {
  background: var(--card);
  margin: 10px -12px;
  padding: 2px 12px 12px;
}
.prod-row {
  width: 100%;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 13px 0;
  text-align: left;
}
.prod-main {
  flex: 1;
  min-width: 0;
}
.prod-name {
  display: block;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.2px;
  line-height: 21px;
}
.prod-pills {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.prod-chev {
  flex: none;
  display: flex;
  margin-top: 4px;
  transition: transform 200ms ease-out;
}
.prod-chev.open {
  transform: rotate(180deg);
}

/* ── the pills ──
   NOT `.pill`: the tab bar's travelling indicator already owns that class and
   is position:absolute, which took these out of flow and stacked every one of
   them at the same coordinates off the left edge. */
.tagpill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 24px;
  padding: 0 9px 0 7px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: -0.05px;
  white-space: nowrap;
  flex: none;
  background: var(--card);
  color: var(--t2);
}
.tagpill-icon {
  display: flex;
  opacity: 0.85;
}
.tagpill-accent {
  background: var(--purple-dim);
  color: var(--t1);
}
.tagpill-strong {
  background: var(--purple-dim);
  color: var(--t1);
}
.tagpill-mixed {
  background: var(--card-hi);
  color: var(--t2);
}
.tagpill-thin {
  background: var(--card);
  color: var(--t3);
}
/* inside an open card the row background is --card, so the pills need to lift */
.prod.open .tagpill {
  background: var(--card-hi);
}
.prod.open .tagpill-accent,
.prod.open .tagpill-strong {
  background: var(--purple-dim);
}

/* ── the opened card ── */
.prod-card {
  padding: 2px 0 4px;
  animation: prod-open 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes prod-open {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}
.prod-evidence {
  margin-bottom: 12px;
  color: var(--t2);
  line-height: 1.5;
}
.prod-evidence b {
  color: var(--t1);
  font-weight: 600;
}
.prod-preview {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 14px 15px;
  border-radius: 16px;
  background: var(--bg);
  color: var(--t1);
  text-decoration: none;
}
.prod-preview-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--t3);
}
.prod-preview-year {
  margin-left: auto;
  font-weight: 600;
}
.prod-preview-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 20px;
  letter-spacing: -0.1px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.prod-preview-cta {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
  color: var(--purple);
}
.prod-preview-empty {
  padding: 12px 2px;
  color: var(--t3);
}
.prod-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}
.prod-btn {
  flex: 1;
  min-width: 140px;
  min-height: 46px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.1px;
  box-shadow: inset 0 0 0 1.5px var(--purple);
  color: var(--purple);
}
.prod-btn.fill {
  background: var(--purple);
  color: var(--bg);
  box-shadow: none;
}
.prod-btn.fill:disabled {
  opacity: 0.65;
}
.prod-btn.wide {
  flex-basis: 100%;
}

/* ============================================================
   Ask AI
   ============================================================ */
.ask {
  display: flex;
  flex-direction: column;
  min-height: 62vh;
}
.ask-thread {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 8px;
}
.ask-empty {
  text-align: center;
  padding: 30px 0 10px;
}
.ask-mark {
  display: inline-grid;
  place-items: center;
  width: 76px;
  height: 76px;
  border-radius: 24px;
  background: var(--card);
}
.ask-empty-line {
  margin: 16px auto 0;
  max-width: 260px;
  font-size: 16px;
  color: var(--t2);
  line-height: 1.5;
}
.ask-examples {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 22px;
}
.ask-example {
  min-height: 46px;
  padding: 12px 16px;
  border-radius: 16px;
  background: var(--card);
  color: var(--t2);
  font-size: 14px;
  text-align: left;
}
.ask-bubble {
  max-width: calc(100% - 60px);
  padding: 12px 15px;
  border-radius: 20px;
  font-size: 15px;
  line-height: 21px;
  letter-spacing: -0.1px;
  white-space: pre-wrap;
}
.ask-bubble.user {
  align-self: flex-end;
  background: var(--purple);
  color: #fff;
}
.ask-bubble.assistant {
  align-self: flex-start;
  background: var(--card);
  color: var(--t1);
}
.ask-dots {
  display: inline-flex;
  gap: 5px;
  padding: 3px 0;
}
.ask-dots i {
  width: 6px;
  height: 6px;
  border-radius: 3px;
  background: var(--t3);
  animation: ask-pulse 1.2s ease-in-out infinite;
}
.ask-dots i:nth-child(2) { animation-delay: 0.15s; }
.ask-dots i:nth-child(3) { animation-delay: 0.3s; }
@keyframes ask-pulse {
  0%, 60%, 100% { opacity: 0.3; }
  30% { opacity: 1; }
}
.ask-composer {
  position: sticky;
  bottom: 0;
  padding: 12px 0 4px;
  background: var(--bg);
}
.ask-input-row {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.ask-input {
  flex: 1;
  min-width: 0;
  min-height: 48px;
  max-height: 132px;
  padding: 13px 16px;
  border-radius: 20px;
  border: 0;
  outline: none;
  resize: none;
  background: var(--card);
  color: var(--t1);
  font: inherit;
  font-size: 15px;
  line-height: 21px;
}
.ask-input::placeholder {
  color: var(--t3);
}
.ask-send {
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 22px;
  display: grid;
  place-items: center;
  background: var(--card);
  color: var(--t3);
  transition: background-color 180ms ease-out, color 180ms ease-out;
}
.ask-send.on {
  background: var(--purple);
  color: var(--bg);
}
.ask-disclaimer {
  margin-top: 8px;
  text-align: center;
  color: var(--t3);
}
@media (prefers-reduced-motion: reduce) {
  .prod-card { animation: none; }
  .ask-dots i { animation: none; opacity: 0.6; }
}

input.content:
import { expect, test } from '@playwright/test';
import type { GlossaryEntry, NutrientReference } from '../../src/lib/api';
import {
  figureDependsOnMenstruation,
  intakeLabel,
  intakeSentence,
  offersMenstrualStatus,
  pickReference,
  resolveIntake,
} from '../../src/lib/intake';

/**
 * Which figure applies to whom — and the one place the honest answer is two
 * figures.
 *
 * `src/lib/intake.ts` is pure, so these run in Node with no browser and no
 * server, next to the rule-table tests. The defect they exist for is silent:
 * `age >= 51` standing in for menopause renders 18 mg to a 46-year-old who
 * stopped menstruating at 44, and nothing on the screen says it guessed.
 */

let seq = 0;
const entry = (over: Partial<GlossaryEntry> & { name: string }): GlossaryEntry => ({
  id: `id-${++seq}`,
  slug: over.name.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
  name: over.name,
  category: 'other',
  mechanism_summary: null,
  storage_notes: null,
  route: 'oral',
  research_summary: null,
  goal_tags: ['Energy'],
  search_keywords: [],
  kind: 'supplement',
  brand: null,
  product_form: 'Capsule',
  label_url: null,
  timing: null,
  timing_note: null,
  evidence: 'mixed',
  ods_url: null,
  ...over,
});

const IRON = entry({ name: 'Thorne Iron Bisglycinate' });
const IRON_SULFATE = entry({ name: 'Nature Made Iron Ferrous Sulfate 65 mg' });
const ZINC = entry({ name: 'AOR Premium Zinc-Copper Balance' });

const ref = (
  age_band: NutrientReference['age_band'],
  sex: NutrientReference['sex'],
  rda: number | null,
  ul: number | null,
  unit = 'mg',
): NutrientReference => ({ glossary_id: 'iron', age_band, sex, rda, ul, unit });

/** The iron rows exactly as migration 0017 seeds them. */
const IRON_ROWS: NutrientReference[] = [
  ref('19-50', 'm', 8, 45),
  ref('19-50', 'f', 18, 45),
  ref('51+', 'm', 8, 45),
  ref('51+', 'f', 8, 45),
  ref('14-18', 'm', 11, 45),
  ref('14-18', 'f', 15, 45),
];

/** A nutrient that differs by age but not by sex — zinc's shape, near enough. */
const ZINC_ROWS: NutrientReference[] = [
  ref('19-50', 'any', 11, 40),
  ref('51+', 'any', 11, 40),
  ref('14-18', 'any', 9, 34),
];

/* ── the band pick, unchanged by any of this ─────────────────────────── */

test('picks the sex-specific row, then the any row, then the adult band', () => {
  expect(pickReference(IRON_ROWS, 34, 'f')?.rda).toBe(18);
  expect(pickReference(ZINC_ROWS, 34, 'f')?.rda).toBe(11);
  expect(pickReference(ZINC_ROWS, 16, 'm')?.rda).toBe(9);
  // an unstated age reads as 19-50, the way every figure in the app does
  expect(pickReference(ZINC_ROWS, null, null)?.rda).toBe(11);
  expect(pickReference(undefined, 34, 'f')).toBeNull();
});

test('leaves every nutrient that is not iron alone', () => {
  expect(offersMenstrualStatus(ZINC, 34, 'f')).toBe(false);
  const i = resolveIntake(ZINC, ZINC_ROWS, 34, 'f', null);
  expect(i.rda).toBe(11);
  expect(i.rdaIfNot).toBeNull();
});

/* ── the defect ──────────────────────────────────────────────────────── */

test('renders both iron figures for a woman under 51 rather than picking one', () => {
  const i = resolveIntake(IRON, IRON_ROWS, 34, 'f', null);
  expect(i.rda).toBe(18);
  expect(i.rdaIfNot).toBe(8);
  expect(i.ul).toBe(45);
});

test('renders both figures at 46, which is where the age proxy was wrong', () => {
  // 45-50 is the band the old `age >= 51` test got wrong in the direction that
  // matters: it showed 18 mg to someone who may have stopped years earlier.
  expect(resolveIntake(IRON, IRON_ROWS, 46, 'f', null).rdaIfNot).toBe(8);
});

test('an unstated age still gets both figures', () => {
  const i = resolveIntake(IRON, IRON_ROWS, null, 'f', null);
  expect(i.rda).toBe(18);
  expect(i.rdaIfNot).toBe(8);
});

test('prefer-not-to-say on sex gets both figures rather than no figure at all', () => {
  // Iron's rows are sex-specific, so this resolved to nothing before and the
  // entry read "no set intake". Both figures are more use than none.
  expect(pickReference(IRON_ROWS, 34, 'na')).toBeNull();
  const i = resolveIntake(IRON, IRON_ROWS, 34, 'na', null);
  expect(i.rda).toBe(18);
  expect(i.rdaIfNot).toBe(8);
});

/* ── the answer ──────────────────────────────────────────────────────── */

test('an answer of yes gives the single 18 mg figure', () => {
  const i = resolveIntake(IRON, IRON_ROWS, 34, 'f', true);
  expect(i.rda).toBe(18);
  expect(i.rdaIfNot).toBeNull();
});

test('an answer of no gives the single 8 mg figure', () => {
  const i = resolveIntake(IRON, IRON_ROWS, 34, 'f', false);
  expect(i.rda).toBe(8);
  expect(i.rdaIfNot).toBeNull();
});

test('the answer beats the age proxy at 51 and over', () => {
  // Menstruating at 52 is exactly the person the proxy fails.
  expect(resolveIntake(IRON, IRON_ROWS, 52, 'f', true).rda).toBe(18);
  expect(resolveIntake(IRON, IRON_ROWS, 52, 'f', false).rda).toBe(8);
});

test('unanswered at 51 and over leaves the published figure alone', () => {
  const i = resolveIntake(IRON, IRON_ROWS, 60, 'f', null);
  expect(i.rda).toBe(8);
  expect(i.rdaIfNot).toBeNull();
});

test('never defaults to 18 for anyone the question was not put to', () => {
  expect(resolveIntake(IRON, IRON_ROWS, 34, 'm', null).rda).toBe(8);
  expect(figureDependsOnMenstruation(IRON, 34, 'm', null)).toBe(false);
});

/* ── who is asked ────────────────────────────────────────────────────── */

test('offers the question to women and to unstated sex, at any adult age', () => {
  expect(offersMenstrualStatus(IRON, 34, 'f')).toBe(true);
  expect(offersMenstrualStatus(IRON, 34, 'na')).toBe(true);
  expect(offersMenstrualStatus(IRON, null, null)).toBe(true);
  expect(offersMenstrualStatus(IRON, 60, 'f')).toBe(true);
  expect(offersMenstrualStatus(IRON, 34, 'm')).toBe(false);
});

test('does not put the question to 13-18 year olds', () => {
  // That band's figures carry adolescent growth as well as menstruation, so
  // there is no published "does not menstruate" figure to pair with them.
  expect(offersMenstrualStatus(IRON, 16, 'f')).toBe(false);
  const i = resolveIntake(IRON, IRON_ROWS, 16, 'f', null);
  expect(i.rda).toBe(15);
  expect(i.rdaIfNot).toBeNull();
});

test('recognises iron by any of its forms, not just the bisglycinate', () => {
  expect(offersMenstrualStatus(IRON_SULFATE, 34, 'f')).toBe(true);
});

test('invents no pair when the catalogue has only one of the two rows', () => {
  const partial = [ref('19-50', 'f', 18, 45)];
  const i = resolveIntake(IRON, partial, 34, 'f', null);
  expect(i.rda).toBe(18);
  expect(i.rdaIfNot).toBeNull();
});

/* ── how it reads ────────────────────────────────────────────────────── */

test('says it depends, in the sentence the spec asks for', () => {
  const i = resolveIntake(IRON, IRON_ROWS, 34, 'f', null);
  expect(intakeLabel(i)).toBe('18 or 8 mg');
  expect(intakeSentence(i)).toBe(
    'Daily target — 18 mg if you menstruate · 8 mg if you don’t. Upper limit 45 mg.',
  );
});

test('drops back to one figure once it has been told', () => {
  const i = resolveIntake(IRON, IRON_ROWS, 34, 'f', false);
  expect(intakeLabel(i)).toBe('8 mg');
  expect(intakeSentence(i)).toBe('Daily target — 8 mg. Upper limit 45 mg.');
});

test('says nothing where nothing is established', () => {
  const i = resolveIntake(ZINC, [], 34, 'f', null);
  expect(intakeLabel(i)).toBeNull();
  expect(intakeSentence(i)).toBeNull();
});

test('leaves the upper limit off when there is not one', () => {
  const i = resolveIntake(ZINC, [ref('19-50', 'any', 30, null, 'mcg')], 34, 'f', null);
  expect(intakeSentence(i)).toBe('Daily target — 30 mcg.');
});

